mapper.select:
select count(1) from fly_article

	and title= #{title}
	and user_id = #{userId}
	and id != #{id}

select count(1) from fly_article_comment

	and article_id= #{articleId}
	and user_id = #{userId}
	and content = #{content}

select , a.content, c.article_id, c.category_id, c.type_id from fly_article a inner join fly_article_category_merge c on a.id=c.article_id
and a.title LIKE CONCAT(CONCAT('%', #{title}),'%') and a.user_id=#{userId} and a.create_time like concat(#{createTime}, '%') and a.status >= 0 and a.status = 0 and a.status = 1 and a.status = 2 and a.status = 3
order by a.${orderby} ${order} limit #{offset},#{rows}

